(() => {
  'use strict';
  function latestMvuData() {
    const messages = getChatMessages('0-{{lastMessageId}}');
    for (let i = messages.length - 1; i >= 0; i--) {
      const d = messages[i]?.data;
      if (d?.stat_data && d?.schema) return _.cloneDeep(d);
    }
    return null;
  }
  const subscription = eventOn('prompt_template_prepare', context => {
    context.mvu = latestMvuData();
  });
  addEventListener('pagehide', () => subscription?.stop?.(), { once: true });
})();
